function buildLocale(name, suit, locale) {
  return {
    name,
    keywords: locale.keywords,
    daily_upright: locale.dailyU,
    daily_reversed: locale.dailyR,
    reading_upright: locale.upright,
    reading_reversed: locale.reversed,
    detail: `${locale.intro}\n\n${locale.upright}\n\n${locale.reversed}\n\n${locale.lesson}`,
  };
}

function buildCard(card) {
  const zh = buildLocale(card.name_cn, card.suit, card.zh);
  return {
    id: card.id,
    number: card.number,
    name_cn: card.name_cn,
    name_en: card.name_en,
    arcana: 'minor',
    suit: card.suit,
    keywords: zh.keywords,
    daily_upright: zh.daily_upright,
    daily_reversed: zh.daily_reversed,
    reading_upright: zh.reading_upright,
    reading_reversed: zh.reading_reversed,
    detail: zh.detail,
    translations: {
      en: buildLocale(card.name_en, card.suit, card.en),
      it: buildLocale(card.name_it, card.suit, card.it),
    },
  };
}

